begin;
select plan(28);
select has_table('app_private','vehicle_tracking_assignments','device assignment history exists');
select has_table('app_private','vehicle_location_observations','immutable observations exist');
select has_table('app_private','current_vehicle_positions','current projection exists');

insert into auth.users(id,email) values ('61000000-0000-4000-8000-000000000001','tracking-office@test.invalid'),('61000000-0000-4000-8000-000000000002','tracking-driver@test.invalid'),('61000000-0000-4000-8000-000000000003','other@test.invalid');
insert into public.user_profiles(user_id,display_name) values ('61000000-0000-4000-8000-000000000001','Tracking Office'),('61000000-0000-4000-8000-000000000002','Tracking Driver'),('61000000-0000-4000-8000-000000000003','Other Driver');
insert into app_private.user_roles(user_id,role_id)
 select '61000000-0000-4000-8000-000000000001'::uuid,role_id from app_private.roles where role_key='operations_manager'
 union all select '61000000-0000-4000-8000-000000000002'::uuid,role_id from app_private.roles where role_key='driver_team'
 union all select '61000000-0000-4000-8000-000000000003'::uuid,role_id from app_private.roles where role_key='driver_team';
insert into app_private.user_access_scopes(user_id,scope_kind,scope_id) values
 ('61000000-0000-4000-8000-000000000001','service_region','51000000-0000-0000-0000-000000000001'),
 ('61000000-0000-4000-8000-000000000002','team','54000000-0000-0000-0000-000000000001');

select is((api.vehicle_tracking_device_register('61000000-0000-4000-8000-000000000001','{"serviceRegionId":"51000000-0000-0000-0000-000000000001","providerKey":"driver-pwa","deviceReference":"PWA-001","deviceName":"Driver Phone","deviceType":"driver_pwa","ownerUserId":"61000000-0000-4000-8000-000000000002","credentialReference":"TRACKING_TEST_DEVICE"}','62000000-0000-4000-8000-000000000001')->>'lifecycle_status'),'registered','device registered');
select is((api.vehicle_tracking_device_lifecycle('61000000-0000-4000-8000-000000000001',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),'active','Issued to test driver','62000000-0000-4000-8000-000000000002')->>'lifecycle_status'),'active','device activated');
select lives_ok($$select api.vehicle_tracking_device_assign('61000000-0000-4000-8000-000000000001',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),'56000000-0000-0000-0000-000000000001','Primary collection vehicle','62000000-0000-4000-8000-000000000003')$$,'device assigned');
select is(jsonb_array_length(api.vehicle_tracking_assignment_history('61000000-0000-4000-8000-000000000001',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'))),1,'assignment history retained');
select is((api.vehicle_tracking_own_device('61000000-0000-4000-8000-000000000002')->>'status'),'active','Driver resolves own active device');

create temporary table tracking_payload(value jsonb);
insert into tracking_payload values(jsonb_build_array(jsonb_build_object('observationId','63000000-0000-4000-8000-000000000001','recordedAt','2026-08-12T14:00:00Z','latitude',-25.75,'longitude',28.24,'accuracyMetres',12,'clientSequence',1,'idempotencyKey','position-1','correlationId','64000000-0000-4000-8000-000000000001','sourceProvider','driver-pwa')));
select is((api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000002',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),(select value from tracking_payload))->'receipts'->0->>'outcome'),'accepted','owned device ingests location');
select is((select count(*) from app_private.vehicle_location_observations),1::bigint,'observation stored once');
select is((api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000002',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),(select value from tracking_payload))->'receipts'->0->>'outcome'),'duplicate','duplicate safe');
select is((api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000002',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),jsonb_build_array(jsonb_build_object('observationId','63000000-0000-4000-8000-000000000001','recordedAt','2026-08-12T14:00:00Z','latitude',-25.74,'longitude',28.24,'accuracyMetres',12,'clientSequence',1,'idempotencyKey','position-1','correlationId','64000000-0000-4000-8000-000000000001','sourceProvider','driver-pwa')))->'receipts'->0->>'outcome'),'conflict','changed duplicate conflicts');
select is((api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000002',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),jsonb_build_array(jsonb_build_object('observationId','63000000-0000-4000-8000-000000000002','recordedAt',now(),'latitude',-91,'longitude',28.24,'accuracyMetres',12,'clientSequence',2,'idempotencyKey','bad-coordinate','correlationId','64000000-0000-4000-8000-000000000002','sourceProvider','driver-pwa')))->'receipts'->0->>'rejectionCode'),'invalid_coordinates','invalid coordinates rejected');
select is((api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000002',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),jsonb_build_array(jsonb_build_object('observationId','63000000-0000-4000-8000-000000000003','recordedAt',now()+interval '10 minutes','latitude',-25.7,'longitude',28.2,'accuracyMetres',12,'clientSequence',3,'idempotencyKey','future','correlationId','64000000-0000-4000-8000-000000000003','sourceProvider','driver-pwa')))->'receipts'->0->>'rejectionCode'),'future_timestamp','future timestamp rejected');
select throws_ok($$select api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000003',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),(select value from tracking_payload))$$,'42501',null,'another device user denied');
select is((select observation_id from app_private.current_vehicle_positions where vehicle_id='56000000-0000-0000-0000-000000000001'),'63000000-0000-4000-8000-000000000001'::uuid,'current projection updated');
select is((api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000002',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),jsonb_build_array(jsonb_build_object('observationId','63000000-0000-4000-8000-000000000004','recordedAt','2026-08-12T13:59:00Z','latitude',-25.8,'longitude',28.3,'accuracyMetres',20,'clientSequence',4,'idempotencyKey','late','correlationId','64000000-0000-4000-8000-000000000004','sourceProvider','driver-pwa')))->'receipts'->0->>'outcome'),'accepted','late offline point accepted historically');
select is((select observation_id from app_private.current_vehicle_positions where vehicle_id='56000000-0000-0000-0000-000000000001'),'63000000-0000-4000-8000-000000000001'::uuid,'late point does not roll projection backward');
select is((api.vehicle_tracking_positions('61000000-0000-4000-8000-000000000001','51000000-0000-0000-0000-000000000001','2026-08-12T14:01:00Z')->0->>'health'),'healthy','tracking health healthy within threshold');
select is((api.vehicle_tracking_positions('61000000-0000-4000-8000-000000000001','51000000-0000-0000-0000-000000000001','2026-08-12T14:10:00Z')->0->>'health'),'stale','tracking health ages to stale');
select throws_ok($$select api.vehicle_tracking_positions('61000000-0000-4000-8000-000000000001',gen_random_uuid(),now())$$,'42501',null,'cross-region read denied');
select throws_ok($$select api.vehicle_tracking_positions('61000000-0000-4000-8000-000000000002','51000000-0000-0000-0000-000000000001',now())$$,'42501',null,'Driver all-vehicle read denied');
select is((api.vehicle_tracking_device_lifecycle('61000000-0000-4000-8000-000000000001',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),'revoked','Test revocation','62000000-0000-4000-8000-000000000004')->>'lifecycle_status'),'revoked','device revoked');
select throws_ok($$select api.vehicle_tracking_device_lifecycle('61000000-0000-4000-8000-000000000001',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),'active','Terminal state cannot reactivate','62000000-0000-4000-8000-000000000005')$$,'22023','invalid_device_transition','revoked device cannot reactivate');
select throws_ok($$select api.vehicle_tracking_ingest_batch('61000000-0000-4000-8000-000000000002',(select vehicle_tracking_device_id from app_private.vehicle_tracking_devices where device_reference='PWA-001'),jsonb_build_array(jsonb_build_object('observationId',gen_random_uuid(),'recordedAt',now(),'latitude',-25.7,'longitude',28.2,'accuracyMetres',12,'clientSequence',5,'idempotencyKey','after-revoke','correlationId',gen_random_uuid(),'sourceProvider','driver-pwa')))$$,'42501',null,'revoked device cannot ingest');
select is((select count(*) from app_private.business_audit_facts where module_key='vehicle-tracking'),4::bigint,'administrative actions audited without per-point audit');
select ok((select count(*)>=3 from app_private.outbox_events where producer_module='vehicle-tracking'),'low-volume device events use outbox');
select throws_ok($$set local role authenticated; insert into app_private.vehicle_location_observations(observation_id) values(gen_random_uuid())$$,'42501',null,'raw browser write denied');
select * from finish(); rollback;
